public class DuplicateResourceDetector extends ResourceXmlDetector implements XmlScanner {

    private static final Implementation IMPLEMENTATION = new Implementation(
            DuplicateResourceDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "DuplicateResource",
            "Duplicate Resources",
            "This check detects duplicate resources within the same resource folder.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            IMPLEMENTATION)
            .addMoreInfo("https://developer.android.com/guide/topics/resources/providing-resources");

    private final Set<String> mySeenResources = new HashSet<>();
    private File myCurrentFolder = null;
    private static final String ATTR_NAME = "name";

    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(ATTR_NAME);
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public void beforeCheckFile(@NonNull XmlContext context) {
        File folder = context.file.getParentFile();
        if (folder != null && !folder.equals(myCurrentFolder)) {
            myCurrentFolder = folder;
            mySeenResources.clear();
        }
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        Element element = attribute.getOwnerElement();
        if (element == null) return;
        String name = attribute.getValue();
        if (name == null || name.isEmpty()) return;
        String resourceType = element.getTagName();
        String resourceKey = resourceType + ":" + name;

        if (!mySeenResources.add(resourceKey)) {
            context.report(ISSUE, attribute, context.getLocation(attribute),
                    "Duplicate resource definition");
        }
    }
}
